1	// Tiny Legend — core types. The contract between the headless simulation
2	// (src/core/**), the content tables (src/content/**), the adapters (src/input,
3	// src/render, src/main.ts) and the tests. Types and literal constants only:
4	// no logic, no imports. See docs/ARCHITECTURE.md §2 and §4. Conventions:
5	// positions are pixels in PLAY-AREA space ((0,0) = top-left of the 16×11 tile
6	// field; the 64 px HUD offset exists only in the renderer); positions may be
7	// fractional but speeds are multiples of 0.25 px/frame so arithmetic is exact;
8	// every timer counts 60 Hz frames and is decremented by step(); hit points are
9	// HALF-HEARTS (3 hearts = 6) so ½-heart damage is an integer.
10	
11	// --- Constants: the fixed NES-style geometry from PLAN.md §2 ---------------
12	
13	export const TILE = 16;
14	export const PLAY_COLS = 16;
15	export const PLAY_ROWS = 11;
16	export const PLAY_W = 256; // PLAY_COLS * TILE
17	export const PLAY_H = 176; // PLAY_ROWS * TILE
18	export const HUD_H = 64;
19	export const SCREEN_W = 256;
20	export const SCREEN_H = 240; // HUD_H + PLAY_H
21	export const FPS = 60;
22	
23	// --- Geometry & input -------------------------------------------------------
24	
25	export type Dir = 'up' | 'down' | 'left' | 'right';
26	
27	export interface Vec { x: number; y: number }
28	
29	/** Axis-aligned rectangle in play-area pixels. */
30	export interface Rect { x: number; y: number; w: number; h: number }
31	
32	/** A collision box relative to an entity's position (top-left of its sprite cell). */
33	export interface BoxDef { ox: number; oy: number; w: number; h: number }
34	
35	/**
36	 * One frame of input, HELD state only. "Pressed this frame" is derived inside
37	 * the core from GameState.prevInput, so scripted inputs and the keyboard
38	 * adapter share one shape.
39	 */
40	export interface Input {
41	  up: boolean;
42	  down: boolean;
43	  left: boolean;
44	  right: boolean;
45	  attack: boolean;
46	  start: boolean;
47	}
48	
49	// --- Content: tiles, rooms, stats, sprites (authored in src/content/**) -----
50	
51	/** A single legend character, e.g. '#', '.', 'D'. */
52	export type TileChar = string;
53	export type RoomId = string;
54	export type SpriteId = string;
55	/** Enemy type name chosen by the designer, e.g. 'octorok'. Behaviour is separate. */
56	export type EnemyKind = string;
57	export type TileKind = 'floor' | 'wall' | 'water' | 'door' | 'lockedDoor' | 'stairs';
58	
59	/** Who may walk onto the tile. Fliers cross water; nobody crosses walls. */
60	export type TilePassable = 'all' | 'fliers' | 'none';
61	
62	export interface TileDef {
63	  char: TileChar;
64	  kind: TileKind;
65	  passable: TilePassable;
66	  blocksProjectiles: boolean;
67	  sprite: SpriteId;
68	}
69	
70	/** Keyed by legend character. */
71	export type TileLegend = Record<TileChar, TileDef>;
72	
73	/** The four MVP archetypes from PLAN.md §2. Content names them; core behaves. */
74	export type EnemyBehaviour = 'shooter' | 'flier' | 'chaser' | 'boss';
75	
76	export type ProjectilePattern = 'facing' | 'aimed' | 'spread3';
77	
78	export interface ProjectileStats {
79	  speed: number; // px/frame
80	  damage: number; // half-hearts
81	  box: BoxDef;
82	  sprite: SpriteId;
83	  pattern: ProjectilePattern;
84	}
85	
86	/** Frame counts that parameterise every enemy state machine. */
87	export interface EnemyTiming {
88	  moveMin: number;
89	  moveMax: number;
90	  pauseMin: number;
91	  pauseMax: number;
92	  windup: number; // frames before an attack fires (0 = never attacks)
93	  cooldown: number; // frames after an attack before the next decision
94	}
95	
96	/** Percent chances; the remainder drops nothing. heart + rupee <= 100. */
97	export interface DropTable { heart: number; rupee: number }
98	
99	export interface EnemyStats {
100	  kind: EnemyKind;
101	  behaviour: EnemyBehaviour;
102	  hp: number; // hits with the basic sword
103	  damage: number; // half-hearts dealt on contact
104	  speed: number; // px/frame
105	  box: BoxDef;
106	  sprite: SpriteId;
107	  timing: EnemyTiming;
108	  projectile: ProjectileStats | null;
109	  drops: DropTable;
110	  knockback: number; // px the enemy is pushed when hit
111	}
112	
113	export type ItemKind = 'sword' | 'key' | 'heart' | 'heartContainer' | 'rupee' | 'artifact';
114	
115	export interface PlayerStats {
116	  speed: number; // px/frame
117	  box: BoxDef; // body box inside the 16×16 sprite cell
118	  startHp: number; // half-hearts (3 hearts = 6)
119	  maxHpCap: number; // half-hearts (5 hearts = 10)
120	  swordBox: Record<Dir, BoxDef>; // sword hitbox per facing, relative to player position
121	  swordActiveFrames: number;
122	  swordCooldownFrames: number;
123	  invulnFrames: number; // i-frames after taking damage
124	  knockbackSpeed: number; // px/frame during knockback
125	  knockbackFrames: number;
126	  sprite: SpriteId;
127	}
128	
129	export interface SpawnDef { kind: EnemyKind; col: number; row: number }
130	
131	/** A placed item is picked up once per game (persisted in GameState.progress). */
132	export interface ItemPlacement { item: ItemKind; col: number; row: number }
133	
134	/** Stepping onto (col,row) — a stairs/cave tile — cuts instantly to another room. */
135	export interface WarpDef { col: number; row: number; to: RoomId; toCol: number; toRow: number }
136	
137	export interface RoomDef {
138	  id: RoomId;
139	  /** Exactly PLAY_ROWS strings of exactly PLAY_COLS legend characters. */
140	  rows: readonly string[];
141	  /** Edge-scroll neighbours. Missing = edge is a hard boundary. */
142	  neighbors: Partial<Record<Dir, RoomId>>;
143	  spawns: readonly SpawnDef[];
144	  items: readonly ItemPlacement[];
145	  warps: readonly WarpDef[];
146	}
147	
148	/** Pixel art as text: one character per palette entry, '.' = transparent. */
149	export interface SpriteDef { rows: readonly string[] }
150	
151	/** Palette character → CSS hex colour, e.g. { g: '#00a800' }. */
152	export type Palette = Record<string, string>;
153	
154	export interface GameTimings {
155	  transitionFrames: number; // edge-scroll duration
156	  gameOverHoldFrames: number; // ignore Start for this long on Game Over
157	  winHoldFrames: number;
158	  dropTtlFrames: number; // dropped hearts/rupees vanish after this
159	}
160	
161	/** The whole game's data. Immutable at runtime; referenced from GameState. */
162	export interface Content {
163	  legend: TileLegend;
164	  rooms: Record<RoomId, RoomDef>;
165	  enemies: Record<EnemyKind, EnemyStats>;
166	  player: PlayerStats;
167	  start: { room: RoomId; col: number; row: number };
168	  sprites: Record<SpriteId, SpriteDef>;
169	  palette: Palette;
170	  timings: GameTimings;
171	}
172	
173	// --- Runtime state ----------------------------------------------------------
174	
175	export interface Knockback { dx: number; dy: number; frames: number } // dx,dy in px/frame
176	
177	/** Shared by every enemy behaviour; each behaviour uses a subset of phases. */
178	export type AiPhase = 'idle' | 'move' | 'windup' | 'attack' | 'cooldown';
179	
180	export interface AiState { phase: AiPhase; timer: number }
181	
182	export interface EntityBase {
183	  id: number;
184	  x: number;
185	  y: number;
186	  box: BoxDef;
187	  alive: boolean; // false = remove at end of frame
188	}
189	
190	export interface Enemy extends EntityBase {
191	  kind: 'enemy';
192	  type: EnemyKind;
193	  behaviour: EnemyBehaviour;
194	  hp: number;
195	  dir: Dir;
196	  ai: AiState;
197	  invuln: number; // frames
198	  knock: Knockback | null;
199	  sprite: SpriteId;
200	}
201	
202	export interface Projectile extends EntityBase {
203	  kind: 'projectile';
204	  vx: number;
205	  vy: number;
206	  damage: number;
207	  sprite: SpriteId;
208	}
209	
210	export interface Pickup extends EntityBase {
211	  kind: 'pickup';
212	  item: ItemKind;
213	  ttl: number | null; // null = placed item, never expires
214	  persistKey: string | null; // set for placed items; recorded in progress on pickup
215	}
216	
217	export type Entity = Enemy | Projectile | Pickup;
218	
