2	// HUD → field (translated by HUD_H, clipped) → mode overlay.
3	
4	import type { Content, GameState } from '..[elided private context: 13 bytes, sha256:1a908798718596940e062a9bc819e8c52b2a88328d8a328923d4f4880c1c85af]';
5	import { HUD_H, PLAY_H, PLAY_W, SCREEN_H, SCREEN_W } from '..[elided private context: 13 bytes, sha256:1a908798718596940e062a9bc819e8c52b2a88328d8a328923d4f4880c1c85af]';
6	import { drawHud, drawOverlay } from '.[elided private context: 6 bytes, sha256:4007d613f3d9754da844a4391bb0382c164cf02b78e513b792bcc05ff823af2f]';
7	import { drawField } from '.[elided private context: 7 bytes, sha256:aebf14dcca69625cd50b21050992e33cd0c4297eb20c6b4bd519432996d46db1]';
8	import { createSpriteCache, type SpriteCache } from '.[elided private context: 10 bytes, sha256:5a97ba00e322c2bdf2ca950406bfe78bce63e7b2b3a3394a0e86dfc0fd4d174d]';
9	
10	export interface Renderer {
11	  readonly canvas: HTMLCanvasElement;
12	  readonly sprites: SpriteCache;
13	  render(state: GameState): void;
14	  fit(boxWidth: number, boxHeight: number): number;
15	}
16	
17	/** Largest integer scale at which 256×240 fits inside the given box. */
18	export function integerScale(boxWidth: number, boxHeight: number): number {
19	  return Math.max(1, Math.floor(Math.min(boxWidth / SCREEN_W, boxHeight / SCREEN_H)));
20	}
21	
22	export function createRenderer(canvas: HTMLCanvasElement, content: Content): Renderer {
23	  canvas.width = SCREEN_W;
24	  canvas.height = SCREEN_H;
25	  canvas.style.imageRendering = 'pixelated';
26	  const maybe = canvas.getContext('2d');
27	  if (!maybe) throw new Error('2D canvas context unavailable');
28	  const ctx: CanvasRenderingContext2D = maybe;
29	  ctx.imageSmoothingEnabled = false;
30	  const sprites = createSpriteCache(content, canvas.ownerDocument);
31	
32	  function fit(boxWidth: number, boxHeight: number): number {
33	    const k = integerScale(boxWidth, boxHeight);
34	    canvas.style.width = `${SCREEN_W * k}px`;
35	    canvas.style.height = `${SCREEN_H * k}px`;
36	    return k;
37	  }
38	
39	  function render(state: GameState): void {
40	    ctx.fillStyle = '#000000';
41	    ctx.fillRect(0, 0, SCREEN_W, SCREEN_H);
42	    drawHud(ctx, state, sprites);
43	    ctx.save();
44	    ctx.translate(0, HUD_H);
45	    ctx.beginPath();
46	    ctx.rect(0, 0, PLAY_W, PLAY_H);
47	    ctx.clip();
48	    if (state.mode.kind !== 'title' && state.mode.kind !== 'gameover' && state.mode.kind !== 'win') {
49	      drawField(ctx, state, sprites);
50	    }
51	    ctx.restore();
52	    drawOverlay(ctx, state, sprites);
53	  }
54	
55	  return { canvas, sprites, render, fit };
56	}
```"}}

