12	export function tickPlayerTimers(state: GameState): void {
13	  const p = state.player;
14	  if (p.invuln > 0) p.invuln--;
15	  if (p.swordTimer > 0) p.swordTimer--;
16	  if (p.swordCooldown > 0) p.swordCooldown--;
17	}
