19	/** DESIGN.md §2: opposite keys cancel; vertical wins over horizontal. */
20	export function inputDir(input: Input): Dir | null {
21	  if (input.up && !input.down) return 'up';
22	  if (input.down && !input.up) return 'down';
23	  if (input.left && !input.right) return 'left';
24	  if (input.right && !input.left) return 'right';
25	  return null;
26	}
