28	/** Would moving the body rect by delta along dir leave the field? */
29	function leavesField(body: Rect, dir: Dir, delta: number): boolean {
30	  switch (dir) {
31	    case 'right': return body.x + body.w + delta > PLAY_W;
32	    case 'left': return body.x - delta < 0;
33	    case 'down': return body.y + body.h + delta > PLAY_H;
34	    case 'up': return body.y - delta < 0;
35	  }
36	}
