38	/**
39	 * Move the player for this frame. Returns the tile that blocked the move (for
40	 * the locked-door check) or null. May switch the mode to transition or warp.
41	 */
42	export function movePlayer(state: GameState): { col: number; row: number } | null {
43	  const p = state.player;
44	  const stats = state.content.player;
45	  if (p.knock) {
46	    const k = p.knock;
47	    slide(state, p, 'x', k.dx, false);
48	    slide(state, p, 'y', k.dy, false);
49	    k.frames--;
50	    if (k.frames <= 0) p.knock = null;
51	    p.moving = false;
52	    return null;
53	  }
54	  if (p.swordTimer > 0) {
55	    p.moving = false;
56	    return null;
57	  }
58	  const dir = inputDir(state.input);
59	  if (!dir) {
60	    p.moving = false;
61	    return null;
62	  }
63	  p.dir = dir;
64	  p.moving = true;
65	  const body = rectOf(p, p.box);
66	  if (leavesField(body, dir, stats.speed)) {
67	    const next = state.content.rooms[state.room.id]?.neighbors[dir];
68	    if (next) {
69	      beginTransition(state, dir);
70	      return null;
71	    }
72	  }
73	  const v = dirVec(dir);
74	  const res = v.x !== 0
75	    ? slide(state, p, 'x', v.x * stats.speed, false)
76	    : slide(state, p, 'y', v.y * stats.speed, false);
77	  const warp = checkWarp(state);
78	  if (warp) {
79	    state.mode = {
80	      kind: 'warp',
81	      to: warp.to,
82	      toCol: warp.toCol,
83	      toRow: warp.toRow,
84	      facing: warp.facing ?? p.dir,
85	      timer: state.content.timings.warpFrames,
86	    };
