// Attack list 21 (headless half): integer scaling for tiny / huge windows and
// the keyboard adapter's blur / OS-repeat handling, driven with synthetic
// events on a bare EventTarget. The browser half is tests/poke/browser.poke.spec.ts.

import { describe, expect, it } from 'vitest';

import { createKeyboard } from '..[elided private context: 24 bytes, sha256:26cc69f00d89e4366560cd5c48c99a08c0d21c89eccd1651e719754ca41f709a]';
import { integerScale } from '..[elided private context: 23 bytes, sha256:34a7fcb4712f7e6e008a50e969d6de222ab91c05e7d48ff641315f8e5f6fe34d]';

class KeyEvent extends Event {
  constructor(type: string, public code: string, public repeat = false) {
    super(type, { cancelable: true });
  }
}

function keyboard(): { kb: ReturnType<typeof createKeyboard>; target: EventTarget } {
  const target = new EventTarget();
  const kb = createKeyboard();
  kb.attach(target as unknown as Window);
  return { kb, target };
}

describe('21a. integer scale', () => {
  it('never drops below 1 and never exceeds the box', () => {
    expect(integerScale(1, 1)).toBe(1);
    expect(integerScale(100, 100)).toBe(1);
    expect(integerScale(255, 239)).toBe(1);
    expect(integerScale(256, 240)).toBe(1);
    expect(integerScale(511, 479)).toBe(1);
    expect(integerScale(512, 480)).toBe(2);
    expect(integerScale(10_000, 10_000)).toBe(39);
    expect(integerScale(100_000, 240)).toBe(1);
    expect(integerScale(0, 0)).toBe(1);
    expect(integerScale(-5, -5)).toBe(1);
    for (let w = 1; w < 4000; w += 37) {
      for (let h = 1; h < 3000; h += 41) {
        const k = integerScale(w, h);
        expect(Number.isInteger(k)).toBe(true);
        expect(k).toBeGreaterThanOrEqual(1);
        if (k > 1) expect(256 * k <= w && 240 * k <= h).toBe(true);
      }
    }
  });
});

describe('21b. keyboard adapter', () => {
  it('OS key repeat (repeat=true keydowns) does not re-press and keyup still releases', () => {
    const { kb, target } = keyboard();
    target.dispatchEvent(new KeyEvent('keydown', 'KeyZ'));
    expect(kb.snapshot().attack).toBe(true);
    for (let i = 0; i < 50; i++) target.dispatchEvent(new KeyEvent('keydown', 'KeyZ', true));
    expect(kb.snapshot().attack).toBe(true);
    target.dispatchEvent(new KeyEvent('keyup', 'KeyZ'));
    expect(kb.snapshot().attack).toBe(false);
    // A repeat that arrives after the release (possible with OS queues) must not re-press.
    target.dispatchEvent(new KeyEvent('keydown', 'KeyZ', true));
    expect(kb.snapshot().attack).toBe(false);
  });

  it('blur releases every held key', () => {
    const { kb, target } = keyboard();
    for (const code of ['ArrowRight', 'KeyW', 'KeyZ', 'Enter']) target.dispatchEvent(new KeyEvent('keydown', code));
    expect(kb.snapshot()).toEqual({ up: true, down: false, left: false, right: true, attack: true, start: true });
    target.dispatchEvent(new Event('blur'));
    expect(kb.snapshot()).toEqual({ up: false, down: false, left: false, right: false, attack: false, start: false });
    // The keyup that arrives later (if any) is harmless.
    target.dispatchEvent(new KeyEvent('keyup', 'ArrowRight'));
    expect(kb.snapshot().right).toBe(false);
  });

  it('both bindings for one action are independent: releasing one keeps the other', () => {
    const { kb, target } = keyboard();
    target.dispatchEvent(new KeyEvent('keydown', 'ArrowLeft'));
    target.dispatchEvent(new KeyEvent('keydown', 'KeyA'));
    target.dispatchEvent(new KeyEvent('keyup', 'ArrowLeft'));
    expect(kb.snapshot().left).toBe(true);
    target.dispatchEvent(new KeyEvent('keyup', 'KeyA'));
    expect(kb.snapshot().left).toBe(false);
  });

  it('arrows, Space and Enter are default-prevented; letters are not', () => {
    const { target } = keyboard();
    const down = new KeyEvent('keydown', 'ArrowUp');
    target.dispatchEvent(down);
    expect(down.defaultPrevented).toBe(true);
    const space = new KeyEvent('keydown', 'Space');
    target.dispatchEvent(space);
    expect(space.defaultPrevented).toBe(true);
    const z = new KeyEvent('keydown', 'KeyZ');
    target.dispatchEvent(z);
    expect(z.defaultPrevented).toBe(false);
  });

  it('an override merges over physical keys and can be cleared', () => {
    const { kb, target } = keyboard();
    target.dispatchEvent(new KeyEvent('keydown', 'ArrowRight'));
    kb.override({ left: true });
    expect(kb.snapshot()).toMatchObject({ left: true, right: true });
    kb.override(null);
    expect(kb.snapshot()).toMatchObject({ left: false, right: true });
  });
});
