// Tiny Legend — runtime state types (split from types.ts to keep every file
// under 300 lines; import them via '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]', which re-exports this file).
// No logic. See docs/ARCHITECTURE.md §2.

import type { BoxDef, Content, Dir, EnemyBehaviour, EnemyKind, Input, ItemKind, RoomId, SpriteId, TileChar } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';

// --- Runtime state ----------------------------------------------------------

export interface Knockback { dx: number; dy: number; frames: number } // dx,dy in px/frame

/** Shared by every enemy behaviour; each behaviour uses a subset of phases. P2 adds chase/hurt/dying. */
export type AiPhase = 'idle' | 'move' | 'windup' | 'attack' | 'cooldown' | 'chase' | 'hurt' | 'dying';

export interface AiState { phase: AiPhase; timer: number }

export interface EntityBase {
  id: number;
  x: number;
  y: number;
  box: BoxDef;
  alive: boolean; // false = remove at end of frame
}

export interface Enemy extends EntityBase {
  kind: 'enemy';
  type: EnemyKind;
  behaviour: EnemyBehaviour;
  hp: number;
  dir: Dir;
  ai: AiState;
  invuln: number; // frames
  knock: Knockback | null;
  sprite: SpriteId;
  vx: number; // P2: flier / boss velocity
  vy: number; // P2
  dir8: number; // P2: flier compass direction 0..7
  phaseFrames: number; // P2: frames spent in the current phase
  spit: number; // P2: boss spit countdown
}

export interface Projectile extends EntityBase {
  kind: 'projectile';
  vx: number;
  vy: number;
  damage: number;
  sprite: SpriteId;
  owner: number; // P2: shooter entity id (one live rock per Octo)
}

export interface Pickup extends EntityBase {
  kind: 'pickup';
  item: ItemKind;
  ttl: number | null; // null = placed item, never expires
  persistKey: string | null; // set for placed items; recorded in progress on pickup
}

export type Entity = Enemy | Projectile | Pickup;

export interface Player {
  x: number;
  y: number;
  box: BoxDef;
  dir: Dir;
  hp: number; // half-hearts
  maxHp: number; // half-hearts
  invuln: number; // frames
  knock: Knockback | null;
  swordTimer: number; // frames left in the swing (0 = not swinging)
  swordCooldown: number;
  moving: boolean; // for the walk animation
}

export interface Inventory {
  sword: boolean;
  keys: number;
  rupees: number; // 0..255
  artifact: boolean;
}

/** The room the player is in, built from RoomDef + progress on entry. */
export interface RoomState {
  id: RoomId;
  /** PLAY_COLS * PLAY_ROWS chars, row-major. Mutated when a door unlocks. */
  tiles: TileChar[];
  entities: Entity[];
  nextEntityId: number;
}

/** P2 (D9): warp/hold/dying are DESIGN.md's Playing sub-states; title/paused carry a Start lock. */
export type Mode =
  | { kind: 'title'; timer: number }
  | { kind: 'playing' }
  | { kind: 'paused'; timer: number }
  | { kind: 'transition'; dir: Dir; from: RoomId; to: RoomId; fromTiles: TileChar[]; frame: number; frames: number }
  | { kind: 'warp'; to: RoomId; toCol: number; toRow: number; facing: Dir; timer: number }
  | { kind: 'hold'; item: ItemKind; timer: number }
  | { kind: 'dying'; timer: number }
  | { kind: 'gameover'; timer: number }
  | { kind: 'win'; timer: number };

/**
 * The entire game. Mutated in place by step(). Everything the simulation
 * reads is here — the RNG state and the content tables included — so the
 * same seed and input sequence always produce the same state.
 */
export interface GameState {
  frame: number;
  rng: number; // mulberry32 state (uint32)
  mode: Mode;
  input: Input; // this frame
  prevInput: Input; // last frame, for press detection
  player: Player;
  inventory: Inventory;
  room: RoomState;
  /** One-time facts that survive death: "item:<room>:<col>,<row>", "door:<room>:<col>,<row>", "boss:<room>". */
  progress: Record<string, boolean>;
  canContinue: boolean; // P2 (D8): a Game Over happened; Title's Enter continues the run
  content: Content;
}

// --- View models and seams --------------------------------------------------

export type HeartSlot = 'full' | 'half' | 'empty';

/** What the HUD renderer draws; computed by core/hud.ts from GameState. */
export interface HudModel {
  hearts: HeartSlot[];
  rupees: number;
  keys: number;
  hasSword: boolean;
  hasArtifact: boolean;
}

/** One step of a scripted playthrough: hold `input` for `frames` frames. */
export interface ScriptStep { frames: number; input: Partial<Input> }

/** The debug handle main.ts exposes as the page-global `__game` for Playwright. */
export interface GameHandle {
  version: string;
  state: GameState;
  step(input?: Partial<Input>): void;
  setInput(input: Partial<Input>): void;
  loadRoom(id: RoomId, col?: number, row?: number): void;
}
// Tiny Legend — core types. The contract between the headless simulation
// (src/core/**), the content tables (src/content/**), the adapters (src/input,
// src/render, src/main.ts) and the tests. Types and literal constants only:
// no logic, no imports. See docs/ARCHITECTURE.md §2 and §4. Conventions:
// positions are pixels in PLAY-AREA space ((0,0) = top-left of the 16×11 tile
// field; the 64 px HUD offset exists only in the renderer); positions may be
