// Keyboard → held Input snapshot (ARCHITECTURE.md §6). Edge detection is the
// core's job; this adapter only reports what is down right now.

import type { Input } from '..[elided private context: 13 bytes, sha256:1a908798718596940e062a9bc819e8c52b2a88328d8a328923d4f4880c1c85af]';

const KEYS: Record<string, keyof Input> = {
  ArrowUp: 'up', KeyW: 'up',
  ArrowDown: 'down', KeyS: 'down',
  ArrowLeft: 'left', KeyA: 'left',
  ArrowRight: 'right', KeyD: 'right',
  KeyZ: 'attack', KeyJ: 'attack',
  Enter: 'start',
};

const PREVENT = new Set(['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space', 'Enter']);

export interface Keyboard {
  attach(target: Window): void;
  snapshot(): Input;
  /** Merge a scripted partial over the physical keys (debug handle). */
  override(partial: Partial<Input> | null): void;
  /** Slice (d): log `{frames, input}` runs to the console for the playthrough script. */
  record(on: boolean): void;
}

export function createKeyboard(): Keyboard {
  const down = new Set<string>();
  let forced: Partial<Input> | null = null;
  let recording = false;
  let lastKey = '';
  let run = 0;

  function snapshot(): Input {
    const input: Input = { up: false, down: false, left: false, right: false, attack: false, start: false };
    for (const code of down) {
      const k = KEYS[code];
      if (k) input[k] = true;
    }
    if (forced) Object.assign(input, forced);
    if (recording) {
      const key = JSON.stringify(input);
      if (key === lastKey) run++;
      else {
        if (lastKey) console.log(`{ frames: ${run}, input: ${compact(lastKey)} },`);
        lastKey = key;
        run = 1;
      }
    }
    return input;
  }

  return {
    attach(target) {
      target.addEventListener('keydown', (e) => {
        if (e.repeat) return;
        if (PREVENT.has(e.code)) e.preventDefault();
        down.add(e.code);
      });
      target.addEventListener('keyup', (e) => {
        if (PREVENT.has(e.code)) e.preventDefault();
        down.delete(e.code);
      });
      target.addEventListener('blur', () => down.clear());
    },
    snapshot,
    override(partial) {
      forced = partial;
    },
    record(on) {
      recording = on;
      lastKey = '';
      run = 0;
    },
  };
}

/** `{"up":true,"down":false,...}` → `{ up: true }` for pasting into a script. */
function compact(json: string): string {
  const obj = JSON.parse(json) as Record<string, boolean>;
  const on = Object.keys(obj).filter((k) => obj[k]);
  return on.length ? `{ ${on.map((k) => `${k}: true`).join(', ')} }` : '{}';
}
