"""/** Tiles on the line `lead` (a column for axis x, a row for axis y) that the rect's perpendicular span overlaps. */
export function leadingEdge(rect: Rect, axis: 'x' | 'y', lead: number): { col: number; row: number }[] {
  const [p0, p1] = axis === 'x' ? span(rect.y, rect.h) : span(rect.x, rect.w);
  const out: { col: number; row: number }[] = [];
  for (let p = p0; p <= p1; p++) out.push(axis === 'x' ? { col: lead, row: p } : { col: p, row: lead });
  return out;
}

