import { isPassable, moveAxis, passableFor, tileAt } from '..[elided private context: 19 bytes, sha256:27371abc9cd7e07c45653b0302ecd5467578414b900808233409d786bcc575b3]';
import type { Rect } from '..[elided private context: 17 bytes, sha256:873b17f27b678735d63174a8b3dad301da371a7a1360b5c1874662d25cf5e593]';
import { addEnemy, makeState, tinyLegend } from '.[elided private context: 10 bytes, sha256:0f977a606dd8cbcde656c76f0742e581c4dda73ccb7a34dabe278e563eb3424d]';

const body = (x: number, y: number): Rect => ({ x, y, w: 12, h: 12 });

describe('tileAt / passableFor', () => {
  it('reads row-major and returns undefined outside the field', () => {
    const s = makeState();
    expect(tileAt(s.room, 0, 0)).toBe('#');
    expect(tileAt(s.room, 3, 3)).toBe('~');
    expect(tileAt(s.room, 16, 0)).toBeUndefined();
    expect(tileAt(s.room, 0, 11)).toBeUndefined();
    expect(tileAt(s.room, -1, 0)).toBeUndefined();
  });

  it('water passes fliers only; out of bounds passes nobody', () => {
    expect(passableFor(tinyLegend['~'], false)).toBe(false);
    expect(passableFor(tinyLegend['~'], true)).toBe(true);
    expect(passableFor(tinyLegend['#'], true)).toBe(false);
    expect(passableFor(undefined, true)).toBe(false);
  });
});

describe('moveAxis', () => {
  it('moves freely across floor', () => {
    const s = makeState();
    expect(moveAxis(s, body(80, 80), 'x', 1.5, false)).toEqual({ moved: 1.5, blocked: null });
    expect(moveAxis(s, body(80, 80), 'y', -1.5, false)).toEqual({ moved: -1.5, blocked: null });
  });

  it('snaps flush against a wall moving right and left', () => {
    const s = makeState();
    // Room A: column 15 is wall on row 1. Body at x=225 (right edge 237) moving +4 → snap to 240.
    expect(moveAxis(s, body(225, 16), 'x', 4, false)).toEqual({ moved: 3, blocked: { col: 15, row: 1 } });
    expect(moveAxis(s, body(220, 16), 'x', 4, false)).toEqual({ moved: 4, blocked: null });
    // Column 0 is wall: body at x=17 moving −4 → snap to 16.
    expect(moveAxis(s, body(17, 16), 'x', -4, false)).toEqual({ moved: -1, blocked: { col: 0, row: 1 } });
  });

  it('snaps against a wall moving up and down', () => {
    const s = makeState();
    expect(moveAxis(s, body(80, 17), 'y', -4, false)).toEqual({ moved: -1, blocked: { col: 5, row: 0 } });
    expect(moveAxis(s, body(80, 145), 'y', 4, false)).toEqual({ moved: 3, blocked: { col: 5, row: 10 } });
  });

  it('never moves backwards when already flush', () => {
    const s = makeState();
    expect(moveAxis(s, body(240, 16), 'x', 2, false).moved).toBe(0);
    expect(moveAxis(s, body(16, 16), 'x', -2, false).moved).toBe(0);
  });

  it('treats out of bounds as solid (open edge, no neighbour)', () => {
    const s = makeState();
    // Row 5 of room A is open at column 15; the field edge still stops the mover.
    expect(moveAxis(s, body(243, 80), 'x', 2, false)).toEqual({ moved: 1, blocked: { col: 16, row: 5 } });
  });

  it('water blocks walkers and passes fliers', () => {
    const s = makeState();
    // Water at cols 3-4, rows 3-4. Body at x=33 (right edge 45) row 3 moving right hits col 3? No: it is inside.
    // Use body left of the water: x=18 (right edge 30) moving +4 → blocked at col 3 (x=48)? 30+4=34 < 48, free.
    expect(moveAxis(s, body(34, 50), 'x', 4, false)).toEqual({ moved: 2, blocked: { col: 3, row: 3 } });
    expect(moveAxis(s, body(34, 50), 'x', 4, true)).toEqual({ moved: 4, blocked: null });
  });

  it('shutter is solid while an enemy lives and open afterwards', () => {
    const s = makeState();
    s.room.tiles[2 * 16 + 8] = 'S';
    expect(isPassable(s, 8, 2, false)).toBe(true);
    const e = addEnemy(s, 'shooter', 5, 5);
    expect(isPassable(s, 8, 2, false)).toBe(false);
    e.alive = false;
    expect(isPassable(s, 8, 2, false)).toBe(true);
  });
});
