describe('mulberry32', () => {
  it('produces the pinned sequence for seed 1', () => {
    const s = createState(tinyContent, 1);
    expect([nextU32(s), nextU32(s), nextU32(s), nextU32(s), nextU32(s)]).toEqual([
      2693262067, 11749833, 2265367787, 4213581821, 4159151403,
    ]);
  });

  it('a different seed gives a different sequence', () => {
    const s = createState(tinyContent, 7);
    expect([nextU32(s), nextU32(s), nextU32(s)]).toEqual([50271532, 266108690, 4195786334]);
  });

  it('randInt / randRange stay in range and chance(100) is always true', () => {
    const s = createState(tinyContent, 3);
    for (let i = 0; i < 1000; i++) {
      const v = randInt(s, 7);
      expect(v).toBeGreaterThanOrEqual(0);
      expect(v).toBeLessThan(7);
      const r = randRange(s, 32, 96);
      expect(r).toBeGreaterThanOrEqual(32);
      expect(r).toBeLessThanOrEqual(96);
    }
    expect(chance(s, 100)).toBe(true);
    expect(chance(s, 0)).toBe(false);
  });
});
