1	// The flier (Bat: Rest⇄Fly, 8-way with a speed ramp and edge reflection,
2	// ignores tiles) and the boss (Gnarl: Patrol→Windup→Spit→Recover).
3	// DESIGN.md §6.3 for behaviour, EnemyStats for numbers.
4	
5	import { enterPhase, rollTimer, tick } from '.[elided private context: 12 bytes, sha256:407d12feea36b967743d62b71e16724083ac5d7d96f41e893cc26b6d9767a1f1]';
6	import { chance, randInt } from '.[elided private context: 6 bytes, sha256:59f3dabede66a9ea6d5651c9e761f8b9ed347dafa7af4cacbee6187c60c99077]';
