1	// Projectile spawning (facing / aimed / spread3 fan) and flight
2	// (ARCHITECTURE.md §3.5; DESIGN.md §6.1). Collision with the player is in combat.ts.
3	
4	import { dirToward, dirVec, rectOf } from '.[elided private context: 7 bytes, sha256:71fee27875c7a562ff537bf33cf473e08d0c30b8515cae5617db13520949e7c7]';
5	import type { Dir, GameState, ProjectileStats, Vec } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
6	import { PLAY_H, PLAY_W, TILE } from '.[elided private context: 8 bytes, sha256:cbf949b82052863751f546583c7ca116efe1c24d24e75b4aa8a4efea674e94f4]';
7	
8	function spawn(state: GameState, origin: Vec, stats: ProjectileStats, vx: number, vy: number, owner: number): void {
9	  state.room.entities.push({
10	    kind: 'projectile',
11	    id: state.room.nextEntityId++,
12	    x: origin.x - stats.box.ox - stats.box.w / 2,
13	    y: origin.y - stats.box.oy - stats.box.h / 2,
14	    box: stats.box,
15	    alive: true,
16	    vx,
17	    vy,
18	    damage: stats.damage,
19	    sprite: stats.sprite,
20	    owner,
21	  });
22	}
23	
24	/** Fire from `origin` (the projectile's centre) in `dir` using the stats' pattern. */
25	export function fire(state: GameState, origin: Vec, stats: ProjectileStats, dir: Dir, owner: number, target?: Vec): void {
26	  const v = dirVec(dir);
27	  switch (stats.pattern) {
28	    case 'facing':
29	      spawn(state, origin, stats, v.x * stats.speed, v.y * stats.speed, owner);
30	      return;
31	    case 'aimed': {
32	      const a = dirVec(target ? dirToward(origin, target, dir) : dir);
33	      spawn(state, origin, stats, a.x * stats.speed, a.y * stats.speed, owner);
34	      return;
35	    }
36	    case 'spread3': {
37	      const perp = { x: -v.y, y: v.x };
38	      const fan = stats.fan ?? [
39	        { forward: stats.speed, side: 0 },
40	        { forward: 0, side: stats.speed },
41	        { forward: 0, side: -stats.speed },
42	      ];
43	      for (const shot of fan) {
44	        spawn(state, origin, stats, v.x * shot.forward + perp.x * shot.side, v.y * shot.forward + perp.y * shot.side, owner);
45	      }
46	    }
47	  }
48	}
49	
50	/** True while a projectile owned by `owner` is in flight (Octo: one live rock). */
51	export function hasLiveProjectile(state: GameState, owner: number): boolean {
52	  return state.room.entities.some((e) => e.kind === 'projectile' && e.alive && e.owner === owner);
53	}
54	
55	export function updateProjectiles(state: GameState): void {
56	  for (const e of state.room.entities) {
57	    if (e.kind !== 'projectile' || !e.alive) continue;
58	    e.x += e.vx;
59	    e.y += e.vy;
60	    const r = rectOf(e, e.box);
61	    if (r.x < 0 || r.y < 0 || r.x + r.w > PLAY_W || r.y + r.h > PLAY_H) {
62	      e.alive = false;
63	      continue;
64	    }
65	    const col = Math.floor((r.x + r.w / 2) / TILE);
66	    const row = Math.floor((r.y + r.h / 2) / TILE);
67	    const ch = state.room.tiles[row * 16 + col];
68	    const def = ch === undefined ? undefined : state.content.legend[ch];
69	    if (def?.blocksProjectiles) e.alive = false;
70	  }
71	}
